public class Main {
    interface Figura {
        double area();
    }

    static class Cuadrado implements Figura {
        double lado;
        Cuadrado(double lado) { this.lado = lado; }
        public double area() { return lado * lado; }
    }

    static class Circulo implements Figura {
        double radio;
        Circulo(double radio) { this.radio = radio; }
        public double area() { return Math.PI * radio * radio; }
    }

    public static void main(String[] args) {
        Figura[] figuras = { new Cuadrado(4), new Circulo(2) };
        for (Figura f : figuras) {
            System.out.printf("%.2f%n", f.area());
        }
    }
}

